startup:
cd /mnt/server && if [ ! -f .env ]; then cat > .env <<EOF
ANTHROPIC_BASE_URL=https://openrouter.ai/api/anthropic
ANTHROPIC_AUTH_TOKEN={{OPENROUTER_API_KEY}}
ANTHROPIC_MODEL={{OPENROUTER_MODEL}}
ASSISTANT_NAME={{ASSISTANT_NAME}}
RUNTIME_MODE=process
PTERODACTYL=1
EOF
else grep -q '^ANTHROPIC_BASE_URL=' .env || echo 'ANTHROPIC_BASE_URL=https://openrouter.ai/api/anthropic' >> .env; grep -q '^ANTHROPIC_AUTH_TOKEN=' .env || echo 'ANTHROPIC_AUTH_TOKEN={{OPENROUTER_API_KEY}}' >> .env; grep -q '^ANTHROPIC_MODEL=' .env || echo 'ANTHROPIC_MODEL={{OPENROUTER_MODEL}}' >> .env; grep -q '^ASSISTANT_NAME=' .env || echo 'ASSISTANT_NAME={{ASSISTANT_NAME}}' >> .env; grep -q '^RUNTIME_MODE=' .env || echo 'RUNTIME_MODE=process' >> .env; grep -q '^PTERODACTYL=' .env || echo 'PTERODACTYL=1' >> .env; fi && npm start
